        </div>
      ) : (
        <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 gap-px bg-secondary-200">
          {isLoading
            ? Array.from({ length: SKELETON_COUNT }).map((_, i) => (
